import React, { useState } from "react";
import axios from "axios";
import "./App.css";

function App() {
  const [query, setQuery] = useState("");
  const [answer, setAnswer] = useState("");
  const [audio, setAudio] = useState(null);
  const [loading, setLoading] = useState(false);

  // ✅ TEXT QUERY
  const handleAsk = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setAnswer("");
    setAudio(null);

    try {
      const res = await axios.get(
        `http://127.0.0.1:8000/api/v1/rag/ask?query=${query}`
      );

      setAnswer(res.data.answer);
    } catch (err) {
      console.error(err);
      setAnswer("❌ Error fetching response");
    }

    setLoading(false);
  };

  // ✅ VOICE QUERY WITH FILE UPLOAD
  const handleVoice = async () => {
    try {
      const input = document.createElement("input");
      input.type = "file";
      input.accept = ".wav";

      input.onchange = async (event) => {
        const file = event.target.files[0];

        if (!file) return;

        setLoading(true);
        setAnswer("🎤 Processing voice...");
        setAudio(null);

        const formData = new FormData();
        formData.append("file", file);

        try {
          const res = await axios.post(
            "http://127.0.0.1:8000/api/v1/voice/ask",
            formData,
            {
              headers: {
                "Content-Type": "multipart/form-data",
              },
            }
          );

          setAnswer(res.data.answer);

          // ✅ audio playback
          setAudio(
            `http://127.0.0.1:8000/static/${res.data.audio_file}`
          );
        } catch (err) {
          console.error(err);
          setAnswer("❌ Voice processing error");
        }

        setLoading(false);
      };

      input.click();
    } catch (err) {
      console.error(err);
      setAnswer("❌ Voice upload failed");
    }
  };

  return (
    <div className="container">
      <h1 className="title">🇮🇳 Sarkari Saathi AI</h1>

      <input
        type="text"
        placeholder="Ask about government schemes..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        className="input-box"
      />

      <div className="button-group">
        <button
          className="btn"
          onClick={handleAsk}
          disabled={loading}
        >
          {loading ? "Loading..." : "Ask"}
        </button>

        <button
          className="btn"
          onClick={handleVoice}
          disabled={loading}
        >
          🎤 Voice Ask
        </button>
      </div>

      <div className="answer-box">
        <h3>Answer:</h3>

        <p>{answer}</p>

        {audio && (
          <audio controls autoPlay>
            <source src={audio} type="audio/mp3" />
          </audio>
        )}
      </div>
    </div>
  );
}

export default App;
